import { describe, expect, it } from "vitest";
import {
  dedupeFeatureSeeds,
  seedIdentityParts,
  stableFeatureJson,
} from "./mapper-reconciliation.js";
import type { FeatureSeed } from "./mappers/types.js";
import type { FeatureRecord } from "./types.js";

function seed(overrides: Partial<FeatureSeed> = {}): FeatureSeed {
  return {
    title: "feature",
    summary: "summary",
    kind: "library",
    source: "test",
    confidence: "high",
    entryPath: "src/index.ts",
    symbol: "entry",
    route: null,
    command: null,
    tags: [],
    trustBoundaries: [],
    ...overrides,
  };
}

function feature(overrides: Partial<FeatureRecord> = {}): FeatureRecord {
  return {
    schemaVersion: 1,
    featureId: "feat_1",
    title: "feature",
    summary: "summary",
    kind: "library",
    source: "test",
    confidence: "high",
    entrypoints: [{ path: "src/index.ts", symbol: null, route: null, command: null }],
    ownedFiles: [],
    contextFiles: [],
    tests: [],
    tags: [],
    trustBoundaries: [],
    status: "pending",
    lock: null,
    findingIds: [],
    patchAttemptIds: [],
    analysisHistory: [],
    createdAt: "2026-01-01T00:00:00.000Z",
    updatedAt: "2026-01-01T00:00:00.000Z",
    ...overrides,
  };
}

describe("mapper reconciliation", () => {
  it("uses one ordered identity definition for IDs and deduplication", () => {
    expect(
      seedIdentityParts(seed({ identityKey: "identity", command: "command", route: "route" })),
    ).toEqual(["library", "test", "src/index.ts", "identity"]);
    expect(seedIdentityParts(seed({ symbol: "symbol" }), null)).toEqual([
      "library",
      "test",
      "src/index.ts",
      "",
    ]);
  });

  it("keeps the first seed for each identity", () => {
    const first = seed({ title: "first" });
    const duplicate = seed({ title: "duplicate" });
    const distinct = seed({ title: "distinct", identityKey: "other" });

    expect(dedupeFeatureSeeds([first, duplicate, distinct])).toEqual([first, distinct]);
  });

  it("ignores volatile feature fields", () => {
    const original = feature();
    const volatileChange = feature({
      createdAt: "2026-02-01T00:00:00.000Z",
      updatedAt: "2026-03-01T00:00:00.000Z",
      lock: {
        lockedByRunId: "run_1",
        lockedAt: "2026-03-01T00:00:00.000Z",
        hostname: "host",
        pid: 1,
      },
      analysisHistory: [
        {
          runId: "run_1",
          kind: "review",
          summary: "clean",
          provider: "mock",
          model: null,
          reasoningEffort: null,
          createdAt: "2026-03-01T00:00:00.000Z",
        },
      ],
    });

    expect(stableFeatureJson(volatileChange)).toBe(stableFeatureJson(original));
    expect(stableFeatureJson(feature({ status: "reviewed" }))).not.toBe(
      stableFeatureJson(original),
    );
  });
});

import { describe, expect, it } from "vitest";
import { defaultConfig } from "./config.js";
import { ClawpatchError } from "./errors.js";
import type { ReviewPromptManifest } from "./prompt.js";
import { validateReviewOutputPartitioned as validatePartitioned } from "./review-validation.js";
import { fixtureRoot, writeFixture } from "./test-helpers.js";
import type { FeatureRecord, ReviewOutput } from "./types.js";

async function validateReviewOutput(
  root: string,
  _feature: FeatureRecord,
  _config: ReturnType<typeof defaultConfig>,
  reviewManifest: ReviewPromptManifest,
  providerOutput: ReviewOutput,
): Promise<ReviewOutput> {
  const result = await validatePartitioned(root, reviewManifest, providerOutput);
  const dropped = result.droppedFindings[0];
  if (dropped !== undefined) {
    throw new ClawpatchError(dropped.message, 8, "malformed-output");
  }
  return { ...providerOutput, findings: result.findings };
}

async function validateReviewOutputPartitioned(
  root: string,
  _feature: FeatureRecord,
  _config: ReturnType<typeof defaultConfig>,
  reviewManifest: ReviewPromptManifest,
  providerOutput: ReviewOutput,
) {
  return validatePartitioned(root, reviewManifest, providerOutput);
}

describe("validateReviewOutput", () => {
  it("accepts evidence that points at included files, existing lines, and matching quotes", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-ok-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts"),
      ),
    ).resolves.toMatchObject({ findings: [{ title: "Bug" }] });
  });

  it("does not reject absolute inspected file metadata", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-inspected-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");
    const providerOutput = output("src/index.ts");
    providerOutput.inspected.files = [`${root}/src/index.ts`];

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        providerOutput,
      ),
    ).resolves.toMatchObject({ findings: [{ title: "Bug" }] });
  });

  it("accepts evidence from linked tests included in review context", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-test-file-");
    await writeFixture(root, "src/index.ts", "const value = 'safe';\n");
    await writeFixture(root, "src/index.test.ts", "const value = 'TODO_BUG';\n");

    await expect(
      validateReviewOutput(
        root,
        {
          ...feature("src/index.ts"),
          tests: [{ path: "src/index.test.ts", command: null }],
        },
        defaultConfig(),
        manifest("src/index.test.ts", { role: "test" }),
        output("src/index.test.ts"),
      ),
    ).resolves.toMatchObject({ findings: [{ title: "Bug" }] });
  });

  it("accepts evidence from files selected after duplicate prompt refs are skipped", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-duplicate-context-");
    await writeFixture(root, "src/index.ts", "const value = 'safe';\n");
    await writeFixture(root, "src/context-one.ts", "const value = 'safe';\n");
    await writeFixture(root, "src/context-two.ts", "const value = 'TODO_BUG';\n");
    const config = defaultConfig();
    config.review.maxContextFiles = 2;

    await expect(
      validateReviewOutput(
        root,
        {
          ...feature("src/index.ts"),
          contextFiles: [
            { path: "src/index.ts", reason: "duplicate owned file" },
            { path: "src/context-one.ts", reason: "context" },
            { path: "src/context-two.ts", reason: "context" },
          ],
        },
        config,
        manifest("src/context-two.ts", { role: "context" }),
        output("src/context-two.ts"),
      ),
    ).resolves.toMatchObject({ findings: [{ title: "Bug" }] });
  });

  it("rejects evidence for files that were not included in review context", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-path-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");
    await writeFixture(root, "src/other.ts", "const value = 'TODO_BUG';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/other.ts"),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });

  it("rejects stale line ranges and quotes that do not match current file text", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-content-");
    await writeFixture(root, "src/index.ts", "const value = 'real';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts", { startLine: 9, endLine: 9, quote: "real" }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts", { startLine: 1, endLine: 1, quote: "missing" }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts", { startLine: 2, endLine: 2, quote: null }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });

  it("rejects quotes that only match outside the cited line range", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-line-quote-");
    await writeFixture(root, "src/index.ts", "const first = 'TODO_BUG';\nconst second = 'safe';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts", { startLine: 2, endLine: 2, quote: "TODO_BUG" }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });

  it("rejects line-only evidence outside the included prompt range", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-prompt-range-");
    await writeFixture(root, "src/index.ts", "const first = 'safe';\nconst second = 'TODO_BUG';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts", {
          includedLineRanges: [{ startLine: 1, endLine: 1 }],
        }),
        output("src/index.ts", { startLine: 2, endLine: 2, quote: null }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });

  it("rejects evidence without a line range or quote", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-empty-evidence-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts"),
        output("src/index.ts", { startLine: null, endLine: null, quote: null }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });

  it("rejects evidence that only exists beyond the truncated prompt text", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-truncated-");
    await writeFixture(root, "src/index.ts", `${"a".repeat(24_000)}\nconst value = 'TODO_TAIL';\n`);

    await expect(
      validateReviewOutput(
        root,
        feature("src/index.ts"),
        defaultConfig(),
        manifest("src/index.ts", { truncated: true }),
        output("src/index.ts", { startLine: null, endLine: null, quote: "TODO_TAIL" }),
      ),
    ).rejects.toMatchObject({ code: "malformed-output" });
  });
});

describe("validateReviewOutputPartitioned", () => {
  it("returns all findings when every finding's evidence is valid", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-partition-ok-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");

    const result = await validateReviewOutputPartitioned(
      root,
      feature("src/index.ts"),
      defaultConfig(),
      manifest("src/index.ts"),
      output("src/index.ts"),
    );

    expect(result.findings).toHaveLength(1);
    expect(result.findings[0]!.title).toBe("Bug");
    expect(result.droppedFindings).toEqual([]);
  });

  it("keeps valid siblings when one finding has a stale quote", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-partition-quote-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");

    const goodFinding = output("src/index.ts").findings[0]!;
    const badFinding: ReviewOutput["findings"][number] = {
      ...goodFinding,
      title: "Stale quote",
      evidence: [
        {
          path: "src/index.ts",
          startLine: 1,
          endLine: 1,
          symbol: null,
          quote: "this text does not exist",
        },
      ],
    };
    const provider: ReviewOutput = {
      findings: [goodFinding, badFinding, { ...goodFinding, title: "Also good" }],
      inspected: { files: ["src/index.ts"], symbols: [], notes: [] },
    };

    const result = await validateReviewOutputPartitioned(
      root,
      feature("src/index.ts"),
      defaultConfig(),
      manifest("src/index.ts"),
      provider,
    );

    expect(result.findings.map((f) => f.title)).toEqual(["Bug", "Also good"]);
    expect(result.droppedFindings).toHaveLength(1);
    const dropped = result.droppedFindings[0]!;
    expect(dropped.path).toEqual(["findings", 1]);
    expect(dropped.layer).toBe("validation");
    expect(dropped.message).toMatch(/quote/iu);
    expect(dropped.sample.length).toBeLessThanOrEqual(200);
  });

  it("drops findings whose evidence file was not included in the prompt", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-partition-included-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");
    await writeFixture(root, "src/other.ts", "const value = 'TODO_BUG';\n");

    const result = await validateReviewOutputPartitioned(
      root,
      feature("src/index.ts"),
      defaultConfig(),
      manifest("src/index.ts"),
      output("src/other.ts"),
    );

    expect(result.findings).toEqual([]);
    expect(result.droppedFindings).toHaveLength(1);
    expect(result.droppedFindings[0]!.layer).toBe("validation");
    expect(result.droppedFindings[0]!.message).toMatch(/not included/iu);
  });

  it("drops findings with empty evidence arrays without throwing", async () => {
    const root = await fixtureRoot("clawpatch-review-validation-partition-empty-");
    await writeFixture(root, "src/index.ts", "const value = 'TODO_BUG';\n");

    const goodFinding = output("src/index.ts").findings[0]!;
    const provider: ReviewOutput = {
      findings: [{ ...goodFinding, title: "No evidence", evidence: [] }, goodFinding],
      inspected: { files: ["src/index.ts"], symbols: [], notes: [] },
    };

    const result = await validateReviewOutputPartitioned(
      root,
      feature("src/index.ts"),
      defaultConfig(),
      manifest("src/index.ts"),
      provider,
    );

    expect(result.findings.map((f) => f.title)).toEqual(["Bug"]);
    expect(result.droppedFindings).toHaveLength(1);
    expect(result.droppedFindings[0]!.path).toEqual(["findings", 0]);
    expect(result.droppedFindings[0]!.message).toMatch(/no evidence/iu);
  });
});

function feature(path: string): FeatureRecord {
  return {
    schemaVersion: 1,
    featureId: "feat_test",
    title: "Test feature",
    summary: "Test feature.",
    kind: "library",
    source: "test",
    confidence: "high",
    entrypoints: [{ path, symbol: null, route: null, command: null }],
    ownedFiles: [{ path, reason: "test" }],
    contextFiles: [],
    tests: [],
    tags: [],
    trustBoundaries: [],
    status: "pending",
    lock: null,
    findingIds: [],
    patchAttemptIds: [],
    analysisHistory: [],
    createdAt: "2026-05-18T00:00:00.000Z",
    updatedAt: "2026-05-18T00:00:00.000Z",
  };
}

function output(
  path: string,
  evidence: {
    startLine?: number | null;
    endLine?: number | null;
    quote?: string | null;
  } = {},
): ReviewOutput {
  return {
    findings: [
      {
        title: "Bug",
        category: "bug",
        severity: "medium",
        confidence: "high",
        evidence: [
          {
            path,
            startLine: "startLine" in evidence ? evidence.startLine! : 1,
            endLine: "endLine" in evidence ? evidence.endLine! : 1,
            symbol: null,
            quote: "quote" in evidence ? evidence.quote! : "TODO_BUG",
          },
        ],
        reasoning: "Reason.",
        reproduction: null,
        recommendation: "Fix it.",
        whyTestsDoNotAlreadyCoverThis: "No test.",
        suggestedRegressionTest: null,
        minimumFixScope: "Small.",
      },
    ],
    inspected: { files: [path], symbols: [], notes: [] },
  };
}

function manifest(
  path: string,
  options: {
    truncated?: boolean;
    readable?: boolean;
    includedLineRanges?: Array<{ startLine: number; endLine: number }>;
    role?: "owned" | "context" | "test";
  } = {},
): ReviewPromptManifest {
  const readable = options.readable ?? true;
  const includedLineRanges = readable
    ? (options.includedLineRanges ?? [{ startLine: 1, endLine: 1 }])
    : [];
  return {
    maxOwnedFiles: defaultConfig().review.maxOwnedFiles,
    maxContextFiles: defaultConfig().review.maxContextFiles,
    includedFiles: [
      {
        path,
        role: options.role ?? "owned",
        bytes: readable ? 1 : 0,
        includedBytes: readable ? 1 : 0,
        includedStartLine: includedLineRanges[0]?.startLine ?? null,
        includedEndLine: includedLineRanges.at(-1)?.endLine ?? null,
        includedLineRanges,
        truncated: options.truncated ?? false,
        readable,
        skippedReason: readable ? null : "unreadable",
      },
    ],
    omittedFiles: [],
    promptBytes: 1,
    approximateTokens: 1,
  };
}

name: ClawSweeper Dispatch

on:
  issues:
    types: [opened, reopened, edited, labeled, unlabeled]
  issue_comment:
    types: [created, edited]
  pull_request_target: # zizmor: ignore[dangerous-triggers] maintainer-owned external dispatch; no checkout or untrusted PR code execution
    types: [opened, reopened, synchronize, ready_for_review, edited, labeled, unlabeled]

permissions:
  contents: read

concurrency:
  group: clawsweeper-dispatch-${{ github.repository }}-${{ github.event_name }}-${{ github.event.comment.id || github.event.issue.number || github.event.pull_request.number || github.run_id }}-${{ endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled') && github.actor || 'dispatchable' }}
  cancel-in-progress: ${{ github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review' }}

jobs:
  dispatch:
    runs-on: ubuntu-latest
    # id-token proves this repository, event, branch, and run to the queue.
    # The job never checks out or executes pull request code.
    permissions:
      contents: read
      id-token: write
    if: ${{ !(endsWith(github.actor, '[bot]') && (github.event.action == 'labeled' || github.event.action == 'unlabeled')) }}
    env:
      SUPERSEDES_IN_PROGRESS: ${{ (github.event.action == 'edited' || github.event.action == 'synchronize' || github.event.action == 'ready_for_review') && 'true' || 'false' }}
    steps:
      - name: Debounce bursty metadata events
        if: ${{ github.event.action == 'labeled' || github.event.action == 'unlabeled' }}
        run: sleep 20

      - name: Pre-filter ClawSweeper comment
        id: comment_filter
        if: ${{ github.event_name == 'issue_comment' }}
        env:
          COMMENT_BODY: ${{ github.event.comment.body }}
        run: |
          set -euo pipefail
          if [[ "$COMMENT_BODY" == *"<!-- clawsweeper-maintainer-opt-in:"* ]]; then
            echo "is_command=false" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          if grep -Eiq '(^|[[:space:]])@(clawsweeper|openclaw-clawsweeper)\b(\[bot\])?|(^|[[:space:]])/(clawsweeper|review|re-review|rerun([[:space:]]+|-)?review|status|explain|fix|build|implement|create([[:space:]]+|-)?pr|fix([[:space:]]+|-)?issue|autofix|auto([[:space:]]+|-)?fix|automerge|auto([[:space:]]+|-)?merge|approve|stop|autoclose)\b' <<< "$COMMENT_BODY"; then
            echo "is_command=true" >> "$GITHUB_OUTPUT"
          else
            echo "is_command=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Dispatch exact ClawSweeper review
        if: ${{ github.event_name != 'issue_comment' }}
        env:
          TARGET_REPO: ${{ github.repository }}
          TARGET_BRANCH: ${{ github.event.repository.default_branch }}
          ITEM_NUMBER: ${{ github.event.issue.number || github.event.pull_request.number }}
          ITEM_KIND: ${{ github.event_name == 'pull_request_target' && 'pull_request' || 'issue' }}
          SOURCE_EVENT: ${{ github.event_name }}
          SOURCE_ACTION: ${{ github.event.action }}
          TARGET_DISPATCH_URL: https://clawsweeper.openclaw.ai/github/target-dispatch
        run: |
          set -euo pipefail
          source_identity_json="$(node <<'NODE'
          const crypto = require("node:crypto");
          const fs = require("node:fs");
          const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, "utf8"));
          const pullRequest = event.pull_request && typeof event.pull_request === "object"
            ? event.pull_request
            : {};
          const issue = event.issue && typeof event.issue === "object" ? event.issue : {};
          const source = process.env.ITEM_KIND === "pull_request" ? pullRequest : issue;
          const headSha = String(pullRequest.head?.sha || "").trim().toLowerCase();
          const baseSha = String(pullRequest.base?.sha || "").trim().toLowerCase();
          const updatedAt = String(pullRequest.updated_at || "").trim();
          const queueClaim = {};
          const result = { queue_claim: queueClaim };
          const sourceUpdatedAt = String(source.updated_at || "").trim();
          if (sourceUpdatedAt && Number.isFinite(Date.parse(sourceUpdatedAt))) {
            queueClaim.source_updated_at = sourceUpdatedAt;
          }
          if (
            typeof source.title === "string" &&
            (source.body === null || typeof source.body === "string") &&
            typeof source.locked === "boolean" &&
            Array.isArray(source.labels)
          ) {
            const labels = [
              ...new Set(
                source.labels
                  .map((label) => String(label?.name || "").trim().toLowerCase())
                  .filter((label) => {
                    if (!label) return false;
                    if (label === "proof: override") return true;
                    if (/^(?:status|rating|proof|merge-risk|impact|issue-rating):/.test(label)) return false;
                    if (/^p[0-3]$/.test(label)) return false;
                    if ([
                      "maturity:stable",
                      "feature: ✨ showcase",
                      "good first issue",
                      "mantis: telegram-visible-proof",
                      "proof: telegram-e2e",
                      "triage: needs-real-behavior-proof",
                      "clawsweeper-recovery-stuck",
                      "no-stale",
                      "stale",
                    ].includes(label)) return false;
                    return !label.startsWith("clawsweeper:") || [
                      "clawsweeper:autofix",
                      "clawsweeper:automerge",
                      "clawsweeper:human-review",
                      "clawsweeper:manual-only",
                      "clawsweeper:bulk-filed",
                    ].includes(label);
                  }),
              ),
            ].sort();
            queueClaim.source_content_revision = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 2,
                  title: source.title,
                  body: source.body || "",
                  locked: source.locked,
                  close_guard_labels: labels,
                }),
              )
              .digest("hex");
          }
          if (process.env.ITEM_KIND === "pull_request") {
            if (/^[0-9a-f]{40}$/.test(headSha)) queueClaim.source_head_sha = headSha;
            if (/^[0-9a-f]{40}$/.test(baseSha)) queueClaim.source_base_sha = baseSha;
            if (typeof pullRequest.draft === "boolean") {
              queueClaim.source_is_draft = pullRequest.draft;
            }
          }
          if (
            process.env.ITEM_KIND !== "pull_request" ||
            !/^[0-9a-f]{40}$/.test(headSha) ||
            !updatedAt
          ) {
            process.stdout.write(JSON.stringify(result));
          } else {
            result.ingress_route = "target_dispatcher";
            result.ingress_fingerprint = crypto
              .createHash("sha256")
              .update(
                JSON.stringify({
                  version: 1,
                  target_repo: String(process.env.TARGET_REPO || "").toLowerCase(),
                  item_number: Number(process.env.ITEM_NUMBER),
                  action: String(process.env.SOURCE_ACTION || ""),
                  head_sha: headSha,
                  updated_at: updatedAt,
                  body: typeof pullRequest.body === "string" ? pullRequest.body : "",
                  label: String(event.label?.name || ""),
                }),
              )
              .digest("hex");
            process.stdout.write(JSON.stringify(result));
          }
          NODE
          )"
          client_payload="$(jq -nc \
            --arg target_repo "$TARGET_REPO" \
            --arg target_branch "$TARGET_BRANCH" \
            --argjson item_number "$ITEM_NUMBER" \
            --arg item_kind "$ITEM_KIND" \
            --arg source_event "$SOURCE_EVENT" \
            --arg source_action "$SOURCE_ACTION" \
